"""Demo results generator: produce a realistic sample results document.

Useful for trying the tool, for tests, and for seeding quickstart examples.
"""

import json
import random
from datetime import datetime, timezone
from pathlib import Path

_SAMPLE = {
    "title": "Q3 Model Evaluation: fraud-xgb vs production baseline",
    "model": {"name": "fraud-xgb", "version": "2026.09.17"},
    "notes": ("Sample results generated by `eval-report-builder sample`. "
              "Do not cite — numbers are synthetic."),
    "splits": [
        {"name": "dev", "samples": 2400,
         "metrics": {"accuracy": 0.9521, "precision": 0.9012, "recall": 0.8834,
                     "f1": 0.8922, "latency_ms": 11.7}},
        {"name": "test", "samples": 8000,
         "metrics": {"accuracy": 0.9466, "precision": 0.8940, "recall": 0.8771,
                     "f1": 0.8855, "latency_ms": 12.1}},
        {"name": "canary", "samples": 500,
         "metrics": {"accuracy": 0.9380, "precision": 0.8712, "recall": 0.8622,
                     "f1": 0.8667, "latency_ms": 12.6}},
    ],
    "baselines": [
        {"name": "production-v42", "splits": [
            {"name": "dev", "samples": 2400,
             "metrics": {"accuracy": 0.9388, "precision": 0.8790, "recall": 0.8611,
                         "f1": 0.8700, "latency_ms": 14.2}},
            {"name": "test", "samples": 8000,
             "metrics": {"accuracy": 0.9311, "precision": 0.8715, "recall": 0.8544,
                         "f1": 0.8629, "latency_ms": 14.8}},
            {"name": "canary", "samples": 500,
             "metrics": {"accuracy": 0.9220, "precision": 0.8502, "recall": 0.8410,
                         "f1": 0.8456, "latency_ms": 15.1}},
        ]},
    ],
    "gates": [
        {"metric": "f1", "split": "test", "op": ">=", "threshold": 0.88,
         "severity": "error", "description": "F1 must not regress below 0.88 on test"},
        {"metric": "latency_ms", "split": "test", "op": "<=", "threshold": 20.0,
         "severity": "error", "description": "p50 latency budget 20ms on test"},
        {"metric": "f1", "split": "canary", "op": ">=", "threshold": 0.85,
         "severity": "warn", "description": "Canary F1 below 0.85 is worth a look"},
    ],
}


def make_sample_results(seed=None, jitter=0.0):
    """Return a deep copy of the sample document.

    seed:  if given, deterministically jitter metric values
    jitter: max absolute perturbation applied to float metrics (0 disables)
    """
    doc = json.loads(json.dumps(_SAMPLE))
    doc["generated_at"] = datetime.now(timezone.utc).isoformat(timespec="seconds")
    if seed is not None:
        rng = random.Random(seed)
        for section in ("splits",):
            for split in doc[section]:
                for key, value in split["metrics"].items():
                    if isinstance(value, float):
                        split["metrics"][key] = round(value + rng.uniform(-jitter, jitter), 4)
        for baseline in doc["baselines"]:
            for split in baseline["splits"]:
                for key, value in split["metrics"].items():
                    if isinstance(value, float):
                        split["metrics"][key] = round(value + rng.uniform(-jitter, jitter), 4)
    return doc


def write_sample(path, seed=None, jitter=0.0):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    doc = make_sample_results(seed=seed, jitter=jitter)
    path.write_text(json.dumps(doc, indent=2), encoding="utf-8")
    return path
